def json_dumps_value(v):
    # Convert Value to JSON-serializable (for json output).
    # Types: None -> None, bool -> bool, int -> int, float -> float or None if nan/inf? Original JSON for nan/inf is null (as observed for avg NaN -> null, parse nan -> null, inf -> null). Good. So nan/inf -> None.
    # str -> str, DateVal -> ISO8601 string (via format_date_json), DurationVal -> "PT...S" (via format_duration_json), list -> list, dict -> dict (recursive).
    if v is None:
        return None
    if isinstance(v, bool):
        return v
    if isinstance(v, int) and not isinstance(v, bool):
        return v
    if isinstance(v, float):
        if math.isnan(v) or math.isinf(v):
            return None
        return v
    if isinstance(v, str):
        return v
    if isinstance(v, DateVal):
        return format_date_json(v.nanos)
    if isinstance(v, DurationVal):
        return format_duration_json(v.nanos)
    if isinstance(v, list):
        return [json_dumps_value(x) for x in v]
    if isinstance(v, dict):
        return {k: json_dumps_value(val) for k,val in v.items()}
    return str(v)

