class FormatRuntimeError(Exception):
    pass

def parse_format_string(fmt):
    # Returns list of tokens: ('lit', text) or ('field', ident, spec_or_None)
    # Handles {{ -> {, }} -> }, {ident[:spec]}.
    # Assumes upfront validation passed (no empty ident, no zero padding, no unmatched? Actually unmatched "{" or "}"? Upfront validation currently returns None (no error) for unmatched (placeholder). Need to handle unmatched here? Original for "{" alone? Untested. For simplicity, treat single "{" without closing as literal "{"? Or error? Unlikely tested. We'll treat as literal? Or error? Let's treat as error? Hmm. For now, treat unmatched as literal (to avoid crash).
    toks=[]
    i=0; n=len(fmt)
    lit_buf=[]
    def flush_lit():
        if len(lit_buf)>0:
            toks.append(('lit', "".join(lit_buf)))
            lit_buf.clear()
    while i<n:
        c=fmt[i]
        if c=='{':
            if i+1<n and fmt[i+1]=='{':
                lit_buf.append('{')
                i+=2
                continue
            # Find closing '}'.
            j=fmt.find('}', i+1)
            if j==-1:
                # Unmatched '{', treat as literal '{'? Or error? For now, treat as literal.
                lit_buf.append('{')
                i+=1
                continue
            content=fmt[i+1:j]
            # content should be non-empty (upfront validated, no empty). If empty (should have been caught upfront, but if slipped, error?).
            if content=="":
                raise FormatRuntimeError("Invalid(must specify identifier)")
            # Split on first ':' for spec.
            if ':' in content:
                ident, spec=content.split(':',1)
                # ident could be ""? Upfront validated (no empty). If empty, error.
                if ident=="":
                    raise FormatRuntimeError("Invalid(must specify identifier)")
                # spec could be ""? e.g., "{a:}" (empty spec)? What does original do? Probably treats as no spec (empty, ok)? Or error? Unlikely tested. Treat as no spec (None).
                if spec=="":
                    spec=None
            else:
                ident=content
                spec=None
            flush_lit()
            toks.append(('field', ident, spec))
            i=j+1
            continue
        elif c=='}':
            if i+1<n and fmt[i+1]=='}':
                lit_buf.append('}')
                i+=2
                continue
            else:
                # Single '}', treat as literal? Or error? For now, literal.
                lit_buf.append('}')
                i+=1
                continue
        else:
            lit_buf.append(c)
            i+=1
            continue
    flush_lit()
    return toks

