def output_legacy_nonagg_streaming(records, out_f):
    col_order=[]
    max_total={}
    for rec in records:
        fields=rec['fields']; raw=rec['raw']
        if len(fields)==0:
            out_f.write(raw+"\n")
            continue
        existing=[k for k in col_order if k in fields]
        new_sorted=sorted([k for k in fields.keys() if k not in col_order])
        display_order=existing+new_sorted
        for k in new_sorted:
            col_order.append(k)
        cells={}
        vs_lens={}
        for k in display_order:
            vs=format_legacy_value(fields[k])
            vs_lens[k]=len(vs)
            cells[k]=f"[{k}={vs}]"
        base_pads={}
        for k in display_order:
            cell_len=len(cells[k])
            if k in max_total:
                hist_tot=max_total[k]
                needed=hist_tot - cell_len
                if needed<4:
                    base_pads[k]=8
                else:
                    base_pads[k]=needed
            else:
                vs_len=vs_lens[k]
                gap_new=max(8, 8+len(k)-vs_len)
                base_pads[k]=gap_new
        line_parts=[]
        for idx_d, k in enumerate(display_order):
            cell=cells[k]
            if idx_d==len(display_order)-1:
                line_parts.append(cell)
            else:
                k_next=display_order[idx_d+1]
                try:
                    idx=col_order.index(k)
                    idx_next=col_order.index(k_next)
                except ValueError:
                    line_parts.append(cell+" "*8)
                    continue
                if idx>idx_next:
                    line_parts.append(cell+" "*8)
                    continue
                intervening=col_order[idx+1:idx_next]
                base=base_pads[k]
                extra=sum((max_total.get(ik, 0)) for ik in intervening)
                total_pad=base+extra
                line_parts.append(cell+" "*total_pad)
        out_f.write("".join(line_parts)+"\n")
        for k in display_order:
            cur_len=len(cells[k])
            new_tot=cur_len+base_pads[k]
            if k in max_total:
                if new_tot>max_total[k]:
                    max_total[k]=new_tot
            else:
                max_total[k]=new_tot

